List<String> separateParenGroups(String parenString) {
  List<String> result = [];
  List<String> current = [];
  int balance = 0;

  for (int i = 0; i < parenString.length; i++) {
    String ch = parenString[i];

    if (ch == "(") {
      balance++;
      current.add(ch);
    } else if (ch == ")") {
      balance--;
      current.add(ch);

      if (balance == 0) {
        result.add(current.join(''));
        current.clear();
      }
    }
  }

  return result;
}
