  int n = grid.length;
  int big = n * n + 1;

  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      if (grid[i][j] == k) {
        List<int> neighbors = [];

        if (i > 0) {
          neighbors.add(grid[i - 1][j]);
        }
        if (j > 0) {
          neighbors.add(grid[i][j - 1]);
        }
        if (i < n - 1) {
          neighbors.add(grid[i + 1][j]);
        }
        if (j < n - 1) {
          neighbors.add(grid[i][j + 1]);
        }

        if (neighbors.isNotEmpty) {
          neighbors.reduce((a, b) => a < b ? a : b);
        }
      }
    }
  }

  List<int> result = [];
  for (int i = 0; i < k; i++) {
    result.add(i.isEven ? 1 : big);
  }

  return result;
}
