bool checkIfLastCharIsALetter(String txt) {
  final lastChar = txt[txt.length - 1];
  if (lastChar.length != 1) {
    return false;
  }
  final code = lastChar.codeUnitAt(0);
  return code >= 0x61 && code <= 0x7a;
}
