    return 'Invalid';
  }

  final name = parts[0];

  if (name.isEmpty) {
    return 'Invalid';
  }

  final startsWithLetter = RegExp(r'^[A-Za-z]');

  if (!startsWithLetter.hasMatch(name[0])) {
    return 'Invalid';
  }

  final digitCount = name.split('').where((c) {
    final code = c.codeUnitAt(0);
    return code >= 48 && code <= 57;
  }).length;

  if (digitCount > 3) {
    return 'Invalid';
  }

  return 'Valid';
}
