List<int> orderByPoints(List<int> nums) {
  final entries = <MapEntry<int, int>>[];

  for (var i = 0; i < nums.length; i++) {
    entries.add(MapEntry(i, nums[i]));
  }

  int points(int n) {
    n = n.abs();
    var sum = 0;
    while (n > 0) {
      sum += n % 10;
      n ~/= 10;
    }
    return sum;
  }

  entries.sort((a, b) {
    final pa = points(a.value);
    final pb = points(b.value);

    if (pa != pb) {
      return pa - pb;
    }

    return a.key - b.key;
  });

  return entries.map((e) => e.value).toList();
}
