List<int> orderByPoints(List<int> nums) {
  int points(int n) {
    return n
        .abs()
        .toRadixString(2)
        .split('')
        .where((c) => c == '1')
        .length;
  }

  final indexed = <MapEntry<int, int>>[];

  for (var i = 0; i < nums.length; i++) {
    indexed.add(MapEntry(i, nums[i]));
  }

  indexed.sort((a, b) {
    final pa = points(a.value);
    final pb = points(b.value);

    if (pa != pb) {
      return pa.compareTo(pb);
    }

    return a.key.compareTo(b.key);
  });

  return indexed.map((e) => e.value).toList();
}
