num doAlgebra(List<String> operator, List<int> operand) {
  final ops = List<String>.from(operator);
  final values = List<num>.from(operand);

  num intPow(num base, num exponent) {
    if (exponent is int && exponent >= 0) {
      num result = 1;
      num b = base;
      int e = exponent;

      while (e > 0) {
        if ((e & 1) == 1) {
          result *= b;
        }
        e >>= 1;
        if (e > 0) {
          b *= b;
        }
      }
      return result;
    }

    return (base as num).toDouble().pow(exponent.toDouble());
  }

  void process(String target) {
    int i = 0;

    while (i < ops.length) {
      if (ops[i] == target) {
        final a = values[i];
        final b = values[i + 1];

        num result;
        switch (target) {
          case '^':
            result = intPow(a, b);
            break;
          case '*':
            result = a * b;
            break;
          case '/':
            result = a / b;
            break;
          case '+':
            result = a + b;
            break;
          default:
            result = a - b;
        }

        values[i] = result;
        values.removeAt(i + 1);
        ops.removeAt(i);
      } else {
        i++;
      }
    }
  }

  process('^');
  process('*');
  process('/');
  process('+');
