void main() {
  final candidate = generateIntegers;

  expect(candidate(2, 10), [2, 4, 6, 8]);
  expect(candidate(10, 2), [2, 4, 6, 8]);
  expect(candidate(132, 2), [2, 4, 6, 8]);
